import { createElement } from 'react'
import { renderToBuffer } from '@react-pdf/renderer'
import * as fs from 'fs'
import * as path from 'path'
import { QuestionnairePdf, ServiceAgreementPdf, OnboardingPackagePdf } from '@fbsi/shared'
import type { FormValues } from '@fbsi/shared'

// Optional sample signature image (generated by PIL) → data URL, to preview the
// drawn/typed signature embedded in the Service Agreement. Falls back to /s/ Name.
function loadSampleSignature(): string {
  try {
    const p = path.join(process.cwd(), 'scripts', 'sample_signature.png')
    return `data:image/png;base64,${fs.readFileSync(p).toString('base64')}`
  } catch {
    return ''
  }
}

