async function main() {
  const planType = '401k'
  console.log(`Generating draft PDFs for: ${planType}...`)

  // 1. Generate Questionnaire Onboarding Summary
  const qElement = createElement(QuestionnairePdf, { planType, values: testValues })
  const qBuffer = await renderToBuffer(qElement)
  const qPath = path.join(process.cwd(), 'Acme_Enterprises-401k-Draft-OnboardingSummary.pdf')
  fs.writeFileSync(qPath, qBuffer)
  console.log(`Generated: ${qPath} (${qBuffer.length} bytes)`)

  // 2. Generate Service Agreement
  const slaElement = createElement(ServiceAgreementPdf, { planType, values: testValues })
  const slaBuffer = await renderToBuffer(slaElement)
  const slaPath = path.join(process.cwd(), 'Acme_Enterprises-401k-Draft-ServiceAgreement.pdf')
  fs.writeFileSync(slaPath, slaBuffer)
  console.log(`Generated: ${slaPath} (${slaBuffer.length} bytes)`)

  // 3. Generate the combined Onboarding Package (cover + SA + summary)
  const pkgElement = createElement(OnboardingPackagePdf, { planType, values: testValues })
  const pkgBuffer = await renderToBuffer(pkgElement)
  const pkgPath = path.join(process.cwd(), 'Acme_Enterprises-401k-Draft-OnboardingPackage.pdf')
  fs.writeFileSync(pkgPath, pkgBuffer)
  console.log(`Generated: ${pkgPath} (${pkgBuffer.length} bytes)`)

  console.log('\nSuccess! Draft PDFs created in project root.')
}

main().catch(err => {
  console.error('Error generating draft PDFs:', err)
  process.exit(1)
})
